local this = UIComponent(Address)
function OnLClickUp() local hostages= UIComponent( UIComponent(Address):Parent() ) local parent = UIComponent( UIComponent( hostages:Parent() ):Parent() ) parent:InterfaceFunction("NotifyDemandHostageCheckboxClicked")
local diplo = UIComponent(this:Parent("diplomacy_panel")) diplo:InterfaceFunction("UpdateHostageButton") end

local this = UIComponent(Address)
local parent = UIComponent(this:Parent("diplomatic_relations"))

sort_columns = { }

function OnMouseLClickUp()
	--parent:InterfaceFunction("OpenNegotiations")
	parent:InterfaceFunction("SetDisplayedFaction", this:GetProperty( "Faction" ) )
end

function OnMouseOn()
	parent:InterfaceFunction("MouseOnFaction", this:GetProperty( "Faction" ) )
end	

function OnMouseOff()
	parent:InterfaceFunction("MouseOffFaction")
end

function OnMouseLDblClick()
	parent:InterfaceFunction("OpenNegotiationsFromDblClick")
end

function Initialise( name, attitude )
	sort_columns = { name, attitude }
end

function LessThan(c, column)
	-- If the sort column is equal to the rhs value then use column 0 (the name)
	local rhs_value = UIComponent(c):GlobalExists("sort_columns")[column+1]
	return (column ~= 0 and sort_columns[column+1] == rhs_value) and sort_columns[1] < UIComponent(c):GlobalExists("sort_columns")[1] or sort_columns[column+1] < rhs_value
end

function OnSelect()
	Component.CallByAddress(Component.GetProperty("ParentPopup"), "LuaCall", "ClosedByCloseButton")
end
